#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)]pub struct RoadmapClosureCertificate{pub closure_id:String,pub first_milestone:u32,pub last_milestone:u32,pub final_assurance_certificate_sha256:String,pub closed_milestones:BTreeSet<u32>,pub closure_sha256:String}
impl RoadmapClosureCertificate{pub fn new(final_assurance:&FinalAssuranceCertificate,first_milestone:u32,last_milestone:u32)->Result<Self,AssuranceError>{final_assurance.verify()?;if first_milestone!=0||last_milestone!=83||last_milestone<first_milestone{return Err(AssuranceError::ClosureDenied("roadmap milestone range".into()));}let closed_milestones=(first_milestone..=last_milestone).collect::<BTreeSet<_>>();let seed=hash_serializable(&(first_milestone,last_milestone,&final_assurance.certificate_sha256,&closed_milestones))?;let closure_id=format!("roadmap-closure-{}",&seed[..24]);let closure_sha256=hash_serializable(&(&closure_id,first_milestone,last_milestone,&final_assurance.certificate_sha256,&closed_milestones))?;Ok(Self{closure_id,first_milestone,last_milestone,final_assurance_certificate_sha256:final_assurance.certificate_sha256.clone(),closed_milestones,closure_sha256})}pub fn verify(&self)->Result<(),AssuranceError>{let expected_set=(self.first_milestone..=self.last_milestone).collect::<BTreeSet<_>>();let expected=hash_serializable(&(&self.closure_id,self.first_milestone,self.last_milestone,&self.final_assurance_certificate_sha256,&self.closed_milestones))?;if self.first_milestone!=0||self.last_milestone!=83||self.closed_milestones!=expected_set||expected!=self.closure_sha256{return Err(AssuranceError::ClosureDenied("roadmap closure certificate".into()));}Ok(())}}
